    "content": "我平时喜欢刷 X（Twitter），有时候看见一个博主分享的信息，博主说的很好听，当时第一时间我也很激动，结果后面研究，发现博主注水了很多，实际没那么好用。 网上有很多都是这样的情况，博主发卖家秀的信息，自己一用就是买家秀了。 然后我就在想，能不能用大模型提前检测下推文的可信度情况，分析信息的质量如何。 成果：Chrome 扩展 —— Noiseless ，主要用来帮网页文本“脱水”，最后的效果就是加强版的 @Grok，需要自己提供 API，我这里面加的都是能免费注册获取的，一般用 Google Gemini 就行…"
