    "content": "大家好，最近折腾了一个叫 CodeMate 的编辑器 App ，主要用来在 iPhone 和 iPad 上看代码（支持了大部分常用的编程语言，200+），偶尔也能顺手改几行。 做它的原因挺简单：有时候人在外面，突然想看一下某个源文件，或者别人发来一段代码，但为了这点事打开电脑又有点麻烦。 它不是用来替代 Xcode 或 VS Code 的，也不能在手机上编译运行项目。定位就是离开电脑时方便看源码，或者临时做一些轻量修改。 阅读文件免费，编辑和部分高级功能需要 Premium ，有订阅和买断，也可以看广告的方式无限白…"
