    "content": "2026年09月26日 9月23日至27日，第五届全球数字贸易博览会在浙江杭州举行。本届数贸会设17万平方米展区，汇聚2008家参展企业及超1.2万名国际客商，呈现人工智能赋能下的数字贸易新图景。 人工智能应用全面开花 人工智能展区内，各种造型的机器人让现场充满未来感。 宇树科技的量产载人变形机甲GD01，以红色金属涂装搭配驾驶舱，近3米高的“大家伙”引来观众排队体验。“它依托高精密伺服驱动系统与变形控制算法，能在不同形态间稳定切换，为文旅展演、特种作业提供全新方案。”宇树科技股份有限公司市场经理陈嘉欣介绍。 星物…"
