    "content": "2026年09月26日 本报北京9月25日电&nbsp;&nbsp;（记者李心萍）全国铁路28日将迎来通车节点，京港高铁雄安至商丘段、哈尔滨至伊春高铁、西渝高铁西安至安康段、宜昌至兴山高铁4条高铁新线集中开通运营。 作为国家“八纵八横”高铁网的核心纵向主干线，京港高铁雄商段的通车，将补齐京港高铁北段的短板，打通华北连通中原、华东的快速通道。 该线路北起雄安站，南至商丘站，正线全长552公里，设计时速350公里，全线布设16座车站，10余座新建车站落地县域，让任丘、肃宁、郓城等县市告别无高铁历史。通车后，雄安至商丘最…"
