    "description": "2026年09月26日 张晓亮摄 \"> 张福新摄 \"> 阿拉善盟委宣传部供图 \"> 又是一年中秋至，圆月东升，清辉遍洒。本报记者来到三处以“月”为名的水边——敦煌月牙泉，大漠环抱一泓清泉，千百年来沙不掩泉，登高望月，别有苍茫；喀纳斯月亮湾，雪山之下河湾如月，天上圆月、水中弯月交相辉映；腾格里月亮湖，沙海之中篝火燃起，游客与家人围坐湖畔，看月升、听民歌，自在团圆。 三地相隔千里，月色却一样动人。愿这轮明月，照亮归途，也照亮每一个团圆夜。 …",
    "content": "2026年09月26日 中秋时节，游客骑着骆驼在甘肃敦煌大漠赏月。 张晓亮摄 \"> 新疆喀纳斯月亮湾美景。 张福新摄 \"> 俯瞰内蒙古阿拉善盟腾格里月亮湖。 阿拉善盟委宣传部供图 \"> 又是一年中秋至，圆月东升，清辉遍洒。本报记者来到三处以“月”为名的水边——敦煌月牙泉，大漠环抱一泓清泉，千百年来沙不掩泉，登高望月，别有苍茫；喀纳斯月亮湾，雪山之下河湾如月，天上圆月、水中弯月交相辉映；腾格里月亮湖，沙海之中篝火燃起，游客与家人围坐湖畔，看月升、听民歌，自在团圆。 三地相隔千里，月色却一样动人。愿这轮明月，照亮归途，…"
