    "author": "",
    "description": "2026年09月26日 中秋赏月，只赏不拍总觉得少了点啥。可月亮又圆又亮，随手一拍，往往只能拍出一圈白色光晕。下面几条拍月亮的小技巧或许能帮到你—— 第一，手要稳。要想拍出清晰的月亮，通常需要用到相机或手机的长焦镜头，很容易因为“手抖”而拍糊。可以适当调高快门速度，或者借助三脚架来稳定相机。如果手边没有三脚架，可以靠在窗台、栏杆上借个力。 第二，压低曝光。月亮在夜空里亮得扎眼，用相机自动测光模式很容易过曝，可以选择“点测光”，将月亮上较…",
    "content": "2026年09月26日 中秋赏月，只赏不拍总觉得少了点啥。可月亮又圆又亮，随手一拍，往往只能拍出一圈白色光晕。下面几条拍月亮的小技巧或许能帮到你—— 第一，手要稳。要想拍出清晰的月亮，通常需要用到相机或手机的长焦镜头，很容易因为“手抖”而拍糊。可以适当调高快门速度，或者借助三脚架来稳定相机。如果手边没有三脚架，可以靠在窗台、栏杆上借个力。 第二，压低曝光。月亮在夜空里亮得扎眼，用相机自动测光模式很容易过曝，可以选择“点测光”，将月亮上较亮的部分作为测光点。如果是用手机拍摄，对焦锁住月亮后，可以把曝光往下拉一拉。宁可…"
