    "content": "2026年09月26日 中秋节到来，月饼集中上市。广式、苏式、京式、滇式等传统月饼与流心、冰皮、桃山皮、杂粮等新式月饼同台竞争，不少消费者陷入选择纠结：传统月饼高糖高油，是否会影响慢病指标？新式月饼真的低脂养生、可以放心多吃吗？月饼究竟该怎么挑、怎么吃才健康？记者采访了北京大学第一医院临床营养科主任医师窦攀。 “市面上月饼品类繁多，消费者无需纠结月饼品牌的优劣。包装上的配料表与营养成分表，才是客观可靠的选购标准。”窦攀介绍。 配料表中原料按照添加量从高到低排序，若白砂糖、麦芽糖浆、植物油、黄油、猪板油等位列配料表前…"
