    "author": "",
    "description": "2026年09月26日 右图：月球主要演化事件年代分布图。 以上图片均为作者提供 \"> “嫦娥奔月”的传说，在民间流传至今。西王母赠给嫦娥的丈夫后羿一颗仙丹，当后羿外出时，他的徒弟逄蒙到嫦娥家抢夺仙丹。嫦娥情急之下吞食仙丹，从地面飞向月球的广寒宫。 据说月亮上还有一只玉兔和一只蟾蜍。嫦娥和它们共同居住在广寒宫里。从人眼能看到的全月球图上可以清晰发现，右侧是一只活泼可爱的小兔子，左侧是一只癞蛤蟆的上半身。吴刚在广寒宫砍伐桂树，永远砍不断伐…",
    "content": "2026年09月26日 左图：地球上能看到的全月球正面图。 右图：月球主要演化事件年代分布图。 以上图片均为作者提供 \"> “嫦娥奔月”的传说，在民间流传至今。西王母赠给嫦娥的丈夫后羿一颗仙丹，当后羿外出时，他的徒弟逄蒙到嫦娥家抢夺仙丹。嫦娥情急之下吞食仙丹，从地面飞向月球的广寒宫。 据说月亮上还有一只玉兔和一只蟾蜍。嫦娥和它们共同居住在广寒宫里。从人眼能看到的全月球图上可以清晰发现，右侧是一只活泼可爱的小兔子，左侧是一只癞蛤蟆的上半身。吴刚在广寒宫砍伐桂树，永远砍不断伐不完。人们看到的月球表面恒久不变，可见“吴刚…"
