    "pub_date": "2026-09-26 08:26:02",
    "author": "",
    "description": "2026年09月26日 中秋前，去福建长汀县的中复村。9月的闽西，稻子刚抽穗，风里带着泥土和草木的气息。这个闽西山区的村庄，有一种说不出的安静。 这里是红军长征的重要出发地之一。红军桥的木梁被岁月雕琢，手摸上去，木纹粗糙。桥柱上那道浅浅的刻痕还在，离地大约1.5米高。当年红军招兵，身高够着这道线，才能扛枪上路。有的孩子身高不够，就悄悄地在鞋底垫上稻草、棉絮，只为能够参加红军。我站在桥边看了许久，想象当年有的年轻人也许身高才刚刚跨过这道线…",
    "content": "2026年09月26日 中秋前，去福建长汀县的中复村。9月的闽西，稻子刚抽穗，风里带着泥土和草木的气息。这个闽西山区的村庄，有一种说不出的安静。 这里是红军长征的重要出发地之一。红军桥的木梁被岁月雕琢，手摸上去，木纹粗糙。桥柱上那道浅浅的刻痕还在，离地大约1.5米高。当年红军招兵，身高够着这道线，才能扛枪上路。有的孩子身高不够，就悄悄地在鞋底垫上稻草、棉絮，只为能够参加红军。我站在桥边看了许久，想象当年有的年轻人也许身高才刚刚跨过这道线，就头也不回地加入了革命的队伍。 中复村的中秋，比别处早一天。当地村民恪守着一项…"
