    "content": "2026年09月26日 在广东，月亮常常不叫作月亮。月亮在这里有很多别称。广府地区和客家地区称之为“月光”，潮汕地区称之为“月娘”，粤西吴川一带，则称之为“月奶”。对于月亮，他们无比敬畏。潮汕地区小朋友从小就知道，不能用手指月亮，否则耳朵就会被月亮割掉，如果不小心指了，就要马上向月亮赔罪，请它原谅。 和全国其他地方一样，每年中秋，广东各地都会拜月亮、吃月饼。不过，这里的月饼与别处是大有不同的。 广府地区最经典的是莲蓉蛋黄月饼。饼皮刷过蛋液，经过烘焙，色泽金黄，香气怡人。切开之后，莲蓉细腻温润，如同羊脂美玉，中间的咸…"
