    "description": "大学是社会的灯塔，其既以“天下为己任”，更以“真理为依归”。澎湃新闻·私家历史联合大学史研究者张淑锵，特别推出“大学堂”系列，回望中国晚清民国高等教育的起源与大学师者的风骨，重温那些关于求是、存真、独立、自由与担当的大学精神与人文传统。不仅重述校史，更要追问：大学为何而立，知识为何而求，教育又应当培养怎样的人。 1900年，庚子战火席卷京城，创办不久的京师大学堂校舍被强占，被迫停办。《辛丑条约》签订后，清廷在内外压力下开启新政，进行自救…",
