    "content": "2026年9月，上海青少年人工智能学院启动第三届学员招生，短短时间报名人数超过了400人，再创新高。后续经过资格审查、笔试、面试等环节后，学院将从中择优录取。 到今年10月，这所由中国福利会少年宫与上海交通大学人工智能学院携手打造的全国首家青少年人工智能学院，将成立满两年。走过两年的创新探索后，这所与“年轻的事业”有关的青学院，正探索将AI人才的培养前置，形成小、初、高贯通式培养机制。 学院的定位是什么？他们是如何招生的？学员的感受如何？未来有什么规划？带着这些问题，澎湃新闻记者近日走进上海青少年人工智能学院在中福…"
