    "content": "记者从国家林草局了解到，来自成都大熊猫繁育研究基地的大熊猫“平平”和“福双”近日将赴美国亚特兰大动物园，开启新一轮大熊猫保护国际合作。 大熊猫“平平”为雄性，2020年3月17日出生，眼圈大而浓黑，辨识度很高。它体形敦实但行动灵活，尤其擅长爬树，常在树杈间休憩。 大熊猫“福双”为雌性，2020年10月18日出生，头顶一小撮蓬松毛发，额头饱满微微前凸。它外形圆润，反应灵敏，具备很强的食物搜寻能力。 中方与亚特兰大动物园的大熊猫保护合作已有25年历史。1999年，大熊猫“伦伦”和“洋洋”来到亚特兰大动物园开启合作，至2…"
