    "content": "9月19日，由商务印书馆主办的柏拉图《理想国》新译本新书首发对谈在涵芬楼书店举行。本次活动以“今天我们为什么还要读《理想国》”为主题，新译本译者、中山大学教授詹文杰与商务印书馆党委书记、董事顾青展开对谈，围绕《理想国》在世界知识谱系中的地位、正义问题的当代意义、百年汉译简史与新译本的翻译原则等话题进行了交流。 对谈现场 “不读《理想国》，无以言西方” 活动伊始，顾青表示，商务印书馆历来重视经典阅读，而《理想国》堪称西方文明知识体系中最具奠基性的文本之一。他请詹文杰从“今天我们为什么还要读《理想国》”这一核心问题谈起…"
