    "content": "新华社联合国9月25日电（记者尚绪谦）伊朗外长阿拉格齐25日称，伊朗已通过卡塔尔向美国转达一个重新开放霍尔木兹海峡的计划，如果美方据此采取必要行动，霍尔木兹海峡可以在七日内重新开放，恢复正常海运。 阿拉格齐在纽约联合国总部举行的记者会上宣布这一消息。他说，自美国接受计划之日起开始计时。计划所要求的美方行动大概需要四到五日落实，因此从美国接受计划的第六日开始，霍尔木兹海峡就可以重新开放。第七日，伊美可以就最终协议开启谈判。 阿拉格齐说，计划要求的美方行动不是新条件，而是6月签署的美伊谅解备忘录中美方已经承诺的内容。如…"
