    "content": "快科技9月26日消息，据MacRumors报道，近日， 部分美国iPhone 18 Pro Max用户反馈遭遇蜂窝网络异常，出现无法连接AT&amp;T网络、eSIM激活失败等问题。 有受影响用户表示，问题发生后，手机无法正常拨打电话、发送短信或使用蜂窝数据。 目前，Reddit及苹果支持社区均已出现类似反馈。 值得注意的是， 美版iPhone 18 Pro Max是苹果本月发布的新款iPhone中，唯一采用高通蜂窝基带的机型。 相比之下，美版iPhone 18 Pro和iPhone Duo均搭载苹果自研C2基带，…"
