    "content": "新华社纽约9月25日电 纽约股市三大股指25日上涨。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨478.64点，收于51828.62点，涨幅为0.93%；标准普尔500种股票指数上涨39.28点，收于7743.41点，涨幅为0.51%；纳斯达克综合指数上涨129.34点，收于27068.72点，涨幅为0.48%。 板块方面，标普500指数十一大板块八涨三跌。科技板块和工业板块分别以0.99%和0.94%的涨幅领涨，能源板块和通信服务板块分别以0.87%和0.65%的跌幅领跌。"
