    "description": "新华社纽约9月25日电 国际油价25日下跌。 截至当天收盘，纽约商品交易所11月交货的轻质原油期货价格下跌2.20美元，收于每桶92.41美元，跌幅为2.33%；11月交货的伦敦布伦特原油期货价格下跌2.28美元，收于每桶104.32美元，跌幅为2.14%。",
