    "content": "快科技9月25日消息，宾利首款纯电 SUV Torcal（托卡尔）日前正式发布，它是宾利继欧陆、飞驰、添越之后的第四大车系，国内预售指导价198.8万起（不含税费、选配），预计明年正式交付。 近日，一张该车后排实拍图在网络上流出，知名车评人韩路看过后毫不留情面地抨击： 这后排座椅、这门板造型、这中央扶手、这配色、这四下漏光的车窗遮阳帘……放国产20万级别车上，车厂都得被用户骂退网了吧 。 从实拍图看， 宾利这款电动车后排表现确实很朴素，大量使用大众集团同源塑料按键，廉价感十足，确实还不如20万级国产车，完全达不到用…"
