    "description": "新华社日本名古屋9月25日电（记者黄浩然、赵紫羽）夜色里，一轮圆月高挂天空，月光与赛场灯光交融。 25日恰逢中秋节，爱知·名古屋亚运会迎来开幕后第六个比赛日。亚运赛场上，“团圆”有了更丰富的注解——不止是阖家围坐的温馨，也是并肩驰骋的豪情；不止是分食月饼的甜蜜，也是以拼搏寄托思念的赤诚。 中秋之夜的女子百米“飞人大战”，陈妤颉不负众望以11秒06打破赛会纪录夺得金牌。赛前聊起过节，17岁的她笑着说：“还没来得及跟家人细聊，父母叮嘱我放宽…",
    "content": "新华社日本名古屋9月25日电（记者黄浩然、赵紫羽）夜色里，一轮圆月高挂天空，月光与赛场灯光交融。 25日恰逢中秋节，爱知·名古屋亚运会迎来开幕后第六个比赛日。亚运赛场上，“团圆”有了更丰富的注解——不止是阖家围坐的温馨，也是并肩驰骋的豪情；不止是分食月饼的甜蜜，也是以拼搏寄托思念的赤诚。 中秋之夜的女子百米“飞人大战”，陈妤颉不负众望以11秒06打破赛会纪录夺得金牌。赛前聊起过节，17岁的她笑着说：“还没来得及跟家人细聊，父母叮嘱我放宽心。比赛比得好，回家（补）过中秋。比不好，回家……也照样过。”一句“也照样过”，…"
