    "link": "http://www.news.cn/20260925/5a91b45787014476acf8155d392a5d47/c.html",
    "pub_date": "2026-09-25 23:16:22",
    "author": "齐菲,宋晨",
    "description": "这是位于八角亭图书馆一侧的兔子灯饰（9月15日摄）。新华社发（澳门特区政府市政署供图） 新华社澳门9月25日电 题：圆月如期 灯火满城——澳门中秋即景 新华社记者齐菲、宋晨 三秋恰半，圆月如期。25日中秋节，一片清辉之下，澳门各地亮起璀璨花灯，举行多彩艺文活动，同庆佳节，共祝团圆。 在大炮台花园，澳门博物馆推出“明空之下——中秋特别开放计划”，配合正在展出的“女皇天下——武则天与神都洛阳”展览，设置卡通版武则天、玉兔充气灯饰以及投壶游戏…",
    "content": "这是位于八角亭图书馆一侧的兔子灯饰（9月15日摄）。新华社发（澳门特区政府市政署供图） 新华社澳门9月25日电 题：圆月如期 灯火满城——澳门中秋即景 新华社记者齐菲、宋晨 三秋恰半，圆月如期。25日中秋节，一片清辉之下，澳门各地亮起璀璨花灯，举行多彩艺文活动，同庆佳节，共祝团圆。 在大炮台花园，澳门博物馆推出“明空之下——中秋特别开放计划”，配合正在展出的“女皇天下——武则天与神都洛阳”展览，设置卡通版武则天、玉兔充气灯饰以及投壶游戏、纸灯笼工作坊等，邀市民旅客在皎皎月华下感受唐风之美。 “非常赏心悦目，感受到很…"
